/// <param name = "_result">A <c>EventHandlerResult</c> object where the <c>VendInvoiceInfoTable</c> FieldId can be returned.</param>
[SubscribesTo(classStr(VendInvoiceTableToLineUpdate),staticDelegateStr(VendInvoiceTableToLineUpdate, convertPurchTableFieldToVendInvoiceDelegate))]
public static void avaVendInvoiceTableToLineUpdate_convertPurchTableFieldToVendInvoiceDelegate(FieldId     _purchTableFieldId,EventHandlerResult   _result)
{
    Switch (_purchTableFieldId)
    {
        case fieldNum (PurchTable, AVAEffectivePrice):
